-- 📚 꼭집 주거 사전 — 당첨자 발표 방법 · 공통 · 2026
-- 재계산 SQL(관리 API에서 그대로 실행 · 읽기만). 범위: 공고일 2026년 · 유형은 housing_type_map 표준값.
-- 확인 2026-10-13 · 실행 4.3초 · 결과:
-- {"anns": 92, "by_std": {"SH 고유": 2, "공공임대(6·10·50년)": 11, "국민임대": 38, "매입임대": 8, "영구임대": 16, "통합공공임대": 4, "행복주택": 10, "행복주택(신혼희망)": 3}, "홈페이지": 83, "홈페이지_ex": ["SH_311349", "SH_311087", "SH_310653"], "문자": 10, "문자_ex": ["SH_311349", "2015122300020898", "2015122300020825"], "마이홈": 4, "마이홈_ex": ["2015122300020699", "2015122300020679", "2015122300020675"], "개별통지": 4, "개별통지_ex": ["2015122300020865", "2015122300020712", "2015122300020649"], "전화문의불가": 0, "전화문의불가_ex": null}
with a as(select distinct on(x.announcement_id)x.announcement_id,x.supply_org org,coalesce(m.std_type,x.housing_type)std,extract(year from coalesce(x.announcement_date,x.created_at::date))::int yr from announcements x left join housing_type_map m on m.source_table='announcements' and m.source=x.source and m.housing_type=x.housing_type order by x.announcement_id,(x.source='LH')desc,x.created_at desc),y as(select p.announcement_id,regexp_replace(p.content_raw,'\s+',' ','g')t,coalesce(r.class_name,c.class_name)cls,a.org,a.std from announcement_policies p join a using(announcement_id) left join policy_row_classes r on r.policy_id=p.id and r.axis='standard' left join policy_category_classes c on c.category=p.category and c.axis='standard' where a.yr=2026)select json_build_object('anns',(select count(distinct announcement_id) from y where cls='당첨·발표'),'by_std',(select json_object_agg(std,n) from(select std,count(distinct announcement_id)n from y where cls='당첨·발표' group by 1)q),'홈페이지',(select count(distinct announcement_id) from y where cls='당첨·발표' and t~'(홈페이지|청약플러스|apply\.lh)'),'홈페이지_ex',(select json_agg(i) from(select distinct announcement_id i from y where cls='당첨·발표' and t~'(홈페이지|청약플러스|apply\.lh)' order by 1 desc limit 3)q),'문자',(select count(distinct announcement_id) from y where cls='당첨·발표' and t~'(문자|SMS|카카오\s*알림|알림톡)'),'문자_ex',(select json_agg(i) from(select distinct announcement_id i from y where cls='당첨·발표' and t~'(문자|SMS|카카오\s*알림|알림톡)' order by 1 desc limit 3)q),'마이홈',(select count(distinct announcement_id) from y where cls='당첨·발표' and t~'마이홈'),'마이홈_ex',(select json_agg(i) from(select distinct announcement_id i from y where cls='당첨·발표' and t~'마이홈' order by 1 desc limit 3)q),'개별통지',(select count(distinct announcement_id) from y where cls='당첨·발표' and t~'개별\s*(통지|통보|안내)'),'개별통지_ex',(select json_agg(i) from(select distinct announcement_id i from y where cls='당첨·발표' and t~'개별\s*(통지|통보|안내)' order by 1 desc limit 3)q),'전화문의불가',(select count(distinct announcement_id) from y where cls='당첨·발표' and t~'(전화|유선)[^.]{0,20}(안내|문의)[^.]{0,20}(불가|하지\s*않)'),'전화문의불가_ex',(select json_agg(i) from(select distinct announcement_id i from y where cls='당첨·발표' and t~'(전화|유선)[^.]{0,20}(안내|문의)[^.]{0,20}(불가|하지\s*않)' order by 1 desc limit 3)q))j;
